# WAR ARENA - referral program UI (gamified card with progress bar + share)
# Run from project root:  powershell -ExecutionPolicy Bypass -File .\install-referral-ui.ps1
$ErrorActionPreference = 'Stop'
Write-Host 'Installing referral UI...' -ForegroundColor Cyan
if (-not (Test-Path 'miniapp')) { Write-Host 'ERROR: run from project root' -ForegroundColor Red; exit 1 }
$b64 = @'

'@
[IO.File]::WriteAllBytes((Join-Path (Get-Location) 'miniapp\index.html'), [Convert]::FromBase64String($b64))
Write-Host '  wrote miniapp/index.html' -ForegroundColor Green
Write-Host 'IMPORTANT: edit BOT_USERNAME in the file to your real bot @username, then:' -ForegroundColor Yellow
Write-Host '  git add miniapp/index.html; git commit -m "referral UI"; git push' -ForegroundColor Cyan